using Microsoft.Extensions.Configuration;

namespace QuickCode.Quickcode.Infrastructure.Data.Helpers;

/// <summary>
/// Identifier quoting for handwritten Dapper SQL (mssql / postgresql / mysql).
/// </summary>
public static class SqlDialect
{
    public static string FromConfiguration(IConfiguration configuration)
    {
        ArgumentNullException.ThrowIfNull(configuration);
        return Normalize(configuration.GetSection("AppSettings:DatabaseType").Get<string>());
    }

    public static string Normalize(string? databaseType)
    {
        if (string.IsNullOrWhiteSpace(databaseType))
            return "mssql";

        return databaseType.Trim().ToLowerInvariant() switch
        {
            "mssql" or "sqlserver" => "mssql",
            "postgresql" or "postgres" or "npgsql" => "postgresql",
            "mysql" or "mariadb" => "mysql",
            "inmemory" => "inMemory",
            _ => throw new NotSupportedException($"Database type '{databaseType}' is not supported.")
        };
    }

    public static string Quote(string identifier, string databaseType)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(identifier);
        var db = Normalize(databaseType);
        return db switch
        {
            "mssql" => $"[{identifier.Replace("]", "]]", StringComparison.Ordinal)}]",
            "postgresql" => $"\"{identifier.Replace("\"", "\"\"", StringComparison.Ordinal)}\"",
            "mysql" => $"`{identifier.Replace("`", "``", StringComparison.Ordinal)}`",
            _ => identifier
        };
    }
}
